const textInput=document.getElementById("text-input"),resultArea=document.getElementById("result-area"),encodeBtn=document.getElementById("encode-btn"),decodeBtn=document.getElementById("decode-btn"),copyBtn=document.getElementById("copy-btn"),clearBtn=document.getElementById("clear-btn");function copyToClipboard(e,t){navigator.clipboard.writeText(e).then(()=>{const e=t.textContent;t.textContent="Copied!",setTimeout(()=>{t.textContent=e},2e3)}).catch(()=>{t.textContent="Failed",setTimeout(()=>{t.textContent="Copy Result"},2e3)})}function resetResult(){resultArea.style.color="",resultArea.style.backgroundColor=""}function showError(e){resultArea.textContent=e,resultArea.style.color="#dc3545",resultArea.style.backgroundColor="#f8d7da"}function showSuccess(e){resultArea.textContent=e,resultArea.style.color="#155724",resultArea.style.backgroundColor="#d4edda"}encodeBtn.addEventListener("click",()=>{const e=textInput.value;if(e)try{resetResult();showSuccess(btoa(unescape(encodeURIComponent(e))))}catch(e){showError("Error encoding text: "+e.message)}else showError("Please enter some text to encode.")}),decodeBtn.addEventListener("click",()=>{const e=textInput.value;if(e)try{resetResult();showSuccess(decodeURIComponent(escape(atob(e))))}catch(e){showError("Invalid Base64 text. Please check your input.")}else showError("Please enter Base64 text to decode.")}),copyBtn.addEventListener("click",()=>{copyToClipboard(resultArea.textContent,copyBtn)}),clearBtn.addEventListener("click",()=>{textInput.value="",resultArea.textContent="Your encoded/decoded text will appear here...",resetResult()}),textInput.addEventListener("input",()=>{const e=textInput.value.trim();if(!e)return;/^[A-Za-z0-9+/]*={0,2}$/.test(e)&&e.length%4==0&&e.length>4?(encodeBtn.textContent="Encode to Base64",decodeBtn.textContent="Decode from Base64 â† Suggested",decodeBtn.style.background="#28a745"):(encodeBtn.textContent="Encode to Base64 â† Suggested",decodeBtn.textContent="Decode from Base64",encodeBtn.style.background="#fa7220",decodeBtn.style.background="#6c757d")}),document.getElementById("back-to-tools-btn").addEventListener("click",function(e){e.preventDefault(),window.location.href="/#utility-tools-section"});